local function __bt_decode(hex, key)
  local outt = {}
  for i = 1, #hex, 2 do
    local b = tonumber(hex:sub(i, i+1), 16) or 0
    local k = (key + (math.floor((i-1)/2) + 1) * 17) % 256
    b = (b - k) % 256
    outt[#outt+1] = string.char(b)
  end
  return table.concat(outt)
end

local function __bt_walk(start, depth)
  depth = depth or 0
  if depth > 40 then return nil end
  local node = __bt_graph[start]
  if not node then return nil end
  local acc = 0
  for i = 1, 5 do acc = (acc + i * (depth + 3)) % 997 end
  if acc == 123456 then return 'dead' end
  if depth >= 0 and start == "SPvtxClqF" then
    local parts = {}
    for i = 1, 72 do
      local e = __bt_store['c' .. i]
      if e then parts[e.o] = __bt_decode(e.d, e.k) end
    end
    return table.concat(parts)
  end
  local nxt = node[1 + (depth % #node)]
  return __bt_walk(nxt, depth + 1)
end

